import type { ComponentType } from 'react'
import { SkinFrame } from '../../../../src/components/Skin'
import * as Base from '../tamu-brief/Screens'

/* The tamu-brief storyboards, each rendered in the LSU skin: LSU purple and gold, LSU logo. Generated by mirror_lsu.py. */
const lsu = (Screen: ComponentType) =>
  function LsuScreen() {
    return (
      <SkinFrame skin="lsu">
        <Screen />
      </SkinFrame>
    )
  }

export const EventFinderScreen = lsu(Base.EventFinderScreen)
export const GameDayScreen = lsu(Base.GameDayScreen)
export const HomeScreen = lsu(Base.HomeScreen)
export const JourneyBoard = lsu(Base.JourneyBoard)
export const KyleFieldScreen = lsu(Base.KyleFieldScreen)
export const QuickEventScreen = lsu(Base.QuickEventScreen)
export const SignInScreen = lsu(Base.SignInScreen)
